begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,auth,pg_catalog;
select plan(33);

select has_table('invoice_series');select has_table('invoices');select has_table('invoice_lines');select has_table('invoice_payments');select has_table('invoice_taxes');select has_table('billing_fiscal_settings');
select is((select count(*)::integer from pg_class where relnamespace='public'::regnamespace and relname in('invoice_series','invoices','invoice_lines','invoice_payments','invoice_taxes','billing_fiscal_settings','invoice_command_idempotency') and relrowsecurity and relforcerowsecurity),7,'RLS y FORCE RLS fiscal');
select function_privs_are('public','issue_preinvoice_invoice',array['uuid','audit_actor_scope','uuid','uuid','uuid','date','uuid','date','text','uuid','uuid'],'authenticated',array[]::text[],'emision solo backend');

insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('b1000000-0000-4000-8000-000000000001','authenticated','authenticated','phase-h-platform@local','',now(),'{}','{}',now(),now()),('b1000000-0000-4000-8000-000000000002','authenticated','authenticated','phase-h-admin@local','',now(),'{}','{}',now(),now()),('b1000000-0000-4000-8000-000000000003','authenticated','authenticated','phase-h-disabled@local','',now(),'{}','{}',now(),now());
insert into profiles(user_id,display_name) values('b1000000-0000-4000-8000-000000000001','Platform H'),('b1000000-0000-4000-8000-000000000002','Admin H'),('b1000000-0000-4000-8000-000000000003','Disabled H');insert into platform_admins(user_id,role,status) values('b1000000-0000-4000-8000-000000000001','superadmin','active');
insert into organizations(id,legal_name,trade_name,status,created_by) values('b2000000-0000-4000-8000-000000000001','Demo H','Demo H','active','b1000000-0000-4000-8000-000000000001'),('b2000000-0000-4000-8000-000000000002','Otra H','Otra H','active','b1000000-0000-4000-8000-000000000001');
insert into organization_memberships(organization_id,user_id,role,status,joined_at) values('b2000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000002','admin_empresa','active',now()),('b2000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000003','admin_empresa','active',now());
insert into organization_module_overrides(organization_id,module_id,override_mode,changed_by,reason) select 'b2000000-0000-4000-8000-000000000001',id,'enabled','b1000000-0000-4000-8000-000000000001','H' from modules where code='billing';
insert into organization_module_overrides(organization_id,module_id,override_mode,changed_by,reason) select 'b2000000-0000-4000-8000-000000000002',id,'disabled','b1000000-0000-4000-8000-000000000001','H' from modules where code='billing';
insert into clients(id,organization_id,legal_name,trade_name,tax_id,billing_email,payment_terms_days,created_by) values('b3000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','Cliente H','Cliente H','A123','cliente@local',30,'b1000000-0000-4000-8000-000000000001');
insert into transport_orders(id,organization_id,order_number,customer_id,transport_type,billable_km,planned_pickup_at,economic_status,created_by) values('b4000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','H-1','b3000000-0000-4000-8000-000000000001','General',300,'2026-08-01','validated','b1000000-0000-4000-8000-000000000001');
insert into transport_order_valuations(id,organization_id,transport_order_id,valuation_number,rate_snapshot_json,input_snapshot_json,breakdown_json,base_amount,supplements_amount,adjustments_amount,total_amount,currency_code,calculated_by,validated_by,validated_at,correlation_id,idempotency_key) values('b5000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000001',1,'{}','{}','{}',346.50,0,0,346.50,'EUR','b1000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001',now(),'b6000000-0000-4000-8000-000000000001','b7000000-0000-4000-8000-000000000001');update transport_orders set current_valuation_id='b5000000-0000-4000-8000-000000000001',economic_status='prefactured' where id='b4000000-0000-4000-8000-000000000001';
insert into billing_preinvoices(id,organization_id,client_id,reference,period_start,period_end,status,currency_code,subtotal_amount,total_amount,created_by,approved_by,approved_at) values('b8000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000001','PRE-2026-0001','2026-08-01','2026-08-31','approved','EUR',346.50,346.50,'b1000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001',now());
insert into billing_preinvoice_lines(organization_id,preinvoice_id,transport_order_id,valuation_id,line_amount,description,created_by) values('b2000000-0000-4000-8000-000000000001','b8000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000001','b5000000-0000-4000-8000-000000000001',346.50,'Servicio H-1','b1000000-0000-4000-8000-000000000001');

select lives_ok($$select configure_invoice_fiscal('b1000000-0000-4000-8000-000000000001','platform','b2000000-0000-4000-8000-000000000001','{"legalName":"Demo H","taxId":"B123","addressLine1":"Calle 1","postalCode":"28001","city":"Madrid","defaultPaymentTermsDays":30}','{"code":"F","name":"Principal","prefix":"F","isPrimary":true,"fiscalYearMode":"calendar_year"}','[{"code":"IVA21","name":"IVA 21 %","kind":"standard","rate":21}]','b9000000-0000-4000-8000-000000000001')$$,'configura emisor, serie e impuestos');
select is((select next_number from invoice_series where organization_id='b2000000-0000-4000-8000-000000000001'),1::bigint,'contador empieza en uno');
select lives_ok($$select issue_preinvoice_invoice('b1000000-0000-4000-8000-000000000001','platform','b2000000-0000-4000-8000-000000000001','b8000000-0000-4000-8000-000000000001',(select id from invoice_series where code='F'),'2026-08-13',(select id from invoice_taxes where code='IVA21'),'2026-09-12',null,'ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001')$$,'convierte prefactura');
select is((select invoice_number from invoices),'F-2026-000001','numero fiscal correlativo');
select is((select subtotal from invoices),346.50::numeric,'base exacta');select is((select tax_total from invoices),72.77::numeric,'IVA redondeado por linea');select is((select total from invoices),419.27::numeric,'total exacto');
select is((select fiscal_snapshot_json->'customer'->>'legalName' from invoices),'Cliente H','snapshot cliente');select is((select status::text from billing_preinvoices where id='b8000000-0000-4000-8000-000000000001'),'converted','prefactura convertida');select is((select economic_status::text from transport_orders where id='b4000000-0000-4000-8000-000000000001'),'invoiced','orden facturada');select is((select count(*)::integer from transport_events where event_type='billing.invoice_issued'),1,'timeline creado');select is((select count(*)::integer from audit_events where action='billing.invoice_issued'),1,'emision auditada');
select lives_ok($$select issue_preinvoice_invoice('b1000000-0000-4000-8000-000000000001','platform','b2000000-0000-4000-8000-000000000001','b8000000-0000-4000-8000-000000000001',(select id from invoice_series where code='F'),'2026-08-13',(select id from invoice_taxes where code='IVA21'),'2026-09-12',null,'ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001')$$,'reintento idempotente');select is((select count(*)::integer from invoices),1,'no duplica emision');
select throws_ok($$update invoice_lines set description='Mutada'$$,'55000','issued invoice lines are immutable','linea emitida inmutable');
select lives_ok($$select record_invoice_payment('b1000000-0000-4000-8000-000000000001','platform','b2000000-0000-4000-8000-000000000001',(select id from invoices),200,'2026-08-20','bank_transfer',null,null,'bc000000-0000-4000-8000-000000000001','bd000000-0000-4000-8000-000000000001')$$,'pago parcial');select is((select status::text from invoices),'partially_paid','estado parcial');select is((select amount_due from invoices),219.27::numeric,'pendiente exacto');
select throws_ok($$select record_invoice_payment('b1000000-0000-4000-8000-000000000001','platform','b2000000-0000-4000-8000-000000000001',(select id from invoices),220,'2026-08-20','cash',null,null,'bc000000-0000-4000-8000-000000000002','bd000000-0000-4000-8000-000000000002')$$,'22023','payment exceeds amount due','impide sobrepago');
select lives_ok($$select record_invoice_payment('b1000000-0000-4000-8000-000000000001','platform','b2000000-0000-4000-8000-000000000001',(select id from invoices),219.27,'2026-08-21','bank_transfer',null,null,'bc000000-0000-4000-8000-000000000003','bd000000-0000-4000-8000-000000000003')$$,'pago total');select is((select status::text from invoices),'paid','estado pagado');select throws_ok($$update invoice_payments set notes='mutado'$$,'55000','invoice payments are append-only','pagos append only');
select throws_ok($$insert into invoice_lines(organization_id,invoice_id,position,description,quantity,unit_price,subtotal,tax_code,tax_name,tax_kind,tax_rate,tax_amount,total,snapshot_json) values('b2000000-0000-4000-8000-000000000002',(select id from invoices),2,'cruce',1,1,1,'x','x','zero',0,0,1,'{}')$$,'23514','invoice tenant mismatch','aislamiento relacional');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);select is((select count(*)::integer from invoices),1,'admin ve su tenant habilitado');select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000003","role":"authenticated"}',true);select is((select count(*)::integer from invoice_series),0,'modulo desactivado no expone datos');reset role;
select * from finish();rollback;
